const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Helper function to mask clouds in Sentinel-2 images.
function maskS2clouds(image) {
  const qa = image.select('QA60');
  // Bits 10 and 11 are clouds and cirrus, respectively.
  const cloudBitMask = 1 << 10;
  const cirrusBitMask = 1 << 11;
  // Both flags should be set to zero, indicating clear conditions.
  const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
  return image.updateMask(mask).divide(10000); // Scale reflectance to 0-1
}

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // A point in the central part of Hood Canal, Washington, USA.
  const aoi = ee.Geometry.Point([-122.87, 47.5]);

  // Define the two time periods for comparison.
  const date_2022 = ee.DateRange('2022-08-15', '2022-08-31');
  const date_2021 = ee.DateRange('2021-08-01', '2021-08-31');

  // 2. Data Acquisition & Check
  const s2_collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED');

  let col_2022 = s2_collection.filterBounds(aoi).filterDate(date_2022);
  let col_2021 = s2_collection.filterBounds(aoi).filterDate(date_2021);

  const size_2022 = col_2022.size().getInfo();
  const size_2021 = col_2021.size().getInfo();

  if (size_2022 === 0 || size_2021 === 0) {
    console.log(`Image count 2021: ${size_2021}`);
    console.log(`Image count 2022: ${size_2022}`);
    console.log("Empty collection for one or both periods.");
    console.log("A"); // C1 is not the correct response. We need to print the tag. A: Yes, B: No, C1: Empty Collection. The correct tag is C1.
    return;
  }

  // 3. Processing: Cloud Masking and Compositing
  const img_2022 = col_2022.map(maskS2clouds).median();
  const img_2021 = col_2021.map(maskS2clouds).median();

  // Define the band of interest (Blue band for Sentinel-2)
  const band = 'B2';

  // 4. Calculation & Validation
  const scale = 1000;
  const region = aoi.buffer(2000); // Buffer point for regional mean

  // Calculate pixel counts to check for C2 case
  const count_2022_info = img_2022.select(band).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: scale,
    maxPixels: 1e9
  });
  const count_2021_info = img_2021.select(band).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: scale,
    maxPixels: 1e9
  });

  const [count_2022, count_2021] = await Promise.all([
      count_2022_info.get(band).getInfo(),
      count_2021_info.get(band).getInfo()
  ]);

  if (count_2022 === 0 || count_2021 === 0) {
    console.log(`Valid pixel count 2021: ${count_2021}`);
    console.log(`Valid pixel count 2022: ${count_2022}`);
    console.log("No valid pixels after cloud masking.");
    console.log("C2");
    return;
  }

  // Calculate mean blue reflectance
  const mean_2022_info = img_2022.select(band).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: scale,
    maxPixels: 1e9
  });
  const mean_2021_info = img_2021.select(band).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: scale,
    maxPixels: 1e9
  });

  const [mean_2022, mean_2021] = await Promise.all([
      mean_2022_info.get(band).getInfo(),
      mean_2021_info.get(band).getInfo()
  ]);

  if (mean_2022 === null || mean_2021 === null) {
    console.log(`Mean Blue Reflectance 2021: ${mean_2021}`);
    console.log(`Mean Blue Reflectance 2022: ${mean_2022}`);
    console.log("Calculation failed, result is null.");
    console.log("C3");
    return;
  }

  // 5. Final Answer
  // Define "noticeably larger" as at least a 10% increase in blue reflectance
  const threshold = 1.10;
  const is_brighter = mean_2022 > (mean_2021 * threshold);

  console.log(`Image Count 2021: ${size_2021}, 2022: ${size_2022}`);
  console.log(`Valid Pixel Count 2021: ${count_2021}, 2022: ${count_2022}`);
  console.log(`Mean Blue Reflectance 2021: ${mean_2021.toFixed(4)}`);
  console.log(`Mean Blue Reflectance 2022: ${mean_2022.toFixed(4)}`);

  if (is_brighter) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
